//! Daemon mode (`piwrite --serve`): newline-delimited JSON over stdio.
//!
//! Protocol: each stdin line is one JSON request `{"path", "content"}`; each
//! request produces exactly one response line on stdout — the same envelope
//! the one-shot CLI prints. Request failures (malformed line, I/O error) are
//! per-line error envelopes and the loop CONTINUES; only transport loss
//! (crash, closed stdout, stdin EOF when the parent goes away) ends the
//! daemon. Always exits 0: a failed request is not a failed process.

use std::io::{self, BufRead, Write};
use std::process::ExitCode;

use serde::Deserialize;

use crate::envelope;

/// One request line. Unknown fields are ignored (liberal in what we accept);
/// a missing `path`/`content` fails deserialization and becomes a
/// `bad request` error envelope rather than a daemon crash. `content` is a
/// JSON string, so it is valid UTF-8 by construction and is written as its
/// exact UTF-8 bytes.
#[derive(Deserialize)]
struct Request {
    path: String,
    content: String,
}

/// Serve until stdin EOF or an unwritable stdout (parent gone).
pub fn serve() -> ExitCode {
    // Own process group: a group-wide kill from the client's group (pibash's
    // kill_tree, job control, CI timeout) must not take the daemon down.
    crate::procgroup::isolate_process_group("piwrite");
    let stdin = io::stdin();
    let stdout = io::stdout();
    let mut out = stdout.lock();
    // One response buffer reused across requests (capacity ratchets to the
    // largest response seen): serialize in place, append the newline, emit
    // with a single write — no per-response String, no re-growth.
    let mut buf = Vec::with_capacity(4 * 1024);
    // The request line is reused the same way: `lines()` would allocate a
    // fresh String per request.
    let mut stdin = stdin.lock();
    let mut line = String::with_capacity(4 * 1024);
    loop {
        line.clear();
        match stdin.read_line(&mut line) {
            Ok(0) | Err(_) => break, // EOF or unreadable stdin: same as EOF
            Ok(_) => {}
        }
        let req = line.trim_end();
        if req.is_empty() {
            continue;
        }
        buf.clear();
        respond_into(req, &mut buf);
        buf.push(b'\n');
        if out.write_all(&buf).and_then(|_| out.flush()).is_err() {
            break; // stdout closed: parent went away, same as EOF
        }
    }
    ExitCode::SUCCESS
}

