use std::process::{Command, Stdio};

use serde_json::{json, Value};

fn scratch(tag: &str) -> PathBuf {
    use std::sync::atomic::{AtomicUsize, Ordering};
    static N: AtomicUsize = AtomicUsize::new(0);
    std::env::temp_dir().join(format!(
        "piwrite-serve-{tag}-{}-{}",
        std::process::id(),
        N.fetch_add(1, Ordering::Relaxed)
    ))
}

/// Feed `lines` to one daemon, close stdin, collect one JSON response per
/// line. Requests are tiny and few, so writing everything before reading
/// cannot fill the stdout pipe buffer.
fn serve(lines: &[String]) -> (Vec<Value>, Option<i32>) {
    let mut child = Command::new(env!("CARGO_BIN_EXE_piwrite"))
        .arg("--serve")
        .stdin(Stdio::piped())
        .stdout(Stdio::piped())
        .stderr(Stdio::piped())
        .spawn()
        .expect("spawn piwrite --serve");
    {
        let stdin = child.stdin.as_mut().expect("piped stdin");
        for line in lines {
            stdin.write_all(line.as_bytes()).expect("write request");
            stdin.write_all(b"\n").expect("write newline");
        }
    } // stdin handle drops: the pipe closes and the daemon sees EOF
    let out = child.wait_with_output().expect("wait for daemon");
    let text = String::from_utf8_lossy(&out.stdout);
    let responses = text
        .lines()
        .map(|l| serde_json::from_str(l).expect("each response line is JSON"))
        .collect();
    (responses, out.status.code())
}

